// ===== Dán vào sketch ESP32 =====
// 0 = đứng yên, 1 = đi bộ, 2 = chạy, 3 = NGÃ
int nhanDangHoatDong(float do_lech, float gia_tri_max, float bien_thien) {
    if (gia_tri_max <= 1.6107f) {
        if (bien_thien <= 0.0414f) {
            return 0;  // dung_yen
        } else {
            return 1;  // di_bo
        }
    } else {
        if (do_lech <= 0.3927f) {
            return 2;  // chay
        } else {
            return 3;  // nga
        }
    }
}
